//! Milestone 2: the Rust level loader must reproduce the legacy `World`'s level-data RAM byte for byte.
//!
//! The expected hashes are generated by the legacy CLI (`--level-ram-hash`) and live in
//! `tests/golden/level-ram.json`. They cover chunks, layout, blocks, collision and palette; the whole-RAM hash in the
//! oracle also includes players/objects/camera and is compared after the full `World` port.

use engine_core::Ram;
use rom_assets::{Archive, LevelData};
use sha2::{Digest, Sha256};
use std::path::PathBuf;

fn repo_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn hex(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    hasher
        .finalize()
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

#[test]
fn collision_sets_load() {
    let root = repo_root();
    let archive_path = root.join("sonicbros3.bin");
    if !archive_path.exists() {
        eprintln!("skip: {} is not present", archive_path.display());
        return;
    }
    let archive = Archive::open(&archive_path).expect("open sonicbros3.bin");
    let sets = rom_assets::load_collision_sets(&archive).expect("collision sets");
    assert_eq!(sets.normal.angles.len(), 256);
    assert_eq!(sets.normal.heights.len(), 256 * 16);
    assert_eq!(sets.normal.widths.len(), 256 * 16);
    assert_eq!(sets.alternate.angles.len(), 256);
    assert_ne!(sets.normal.name, sets.alternate.name);
}

#[test]
fn level_data_matches_the_legacy_world() {
    let root = repo_root();
    let archive_path = root.join("sonicbros3.bin");
    if !archive_path.exists() {
        eprintln!(
            "skip: {} is not present (ROM-derived archive, intentionally not committed)",
            archive_path.display()
        );
        return;
    }
    let expected_text =
        std::fs::read_to_string(root.join("tests/golden/level-ram.json")).expect("level-ram.json");
    let expected_text = expected_text
        .strip_prefix('\u{feff}')
        .unwrap_or(&expected_text);
    let expected: serde_json::Value =
        serde_json::from_str(expected_text).expect("valid level-ram.json");
    let rows = expected.as_array().expect("level-ram.json is an array");
    assert_eq!(rows.len(), 3);
    let archive = Archive::open(&archive_path).expect("open sonicbros3.bin");

    for row in rows {
        let zone = row["zone"].as_u64().expect("zone") as u16;
        let act = row["act"].as_u64().expect("act") as u16;
        let level = LevelData::load(&archive, zone, act)
            .unwrap_or_else(|e| panic!("load zone ${zone:02X} act {act}: {e}"));

        // `tiles` in the oracle is `Level.TileCount` = composed VRAM (level art + load-time PLCs), 2048 tiles.
        // This milestone loads level art only; PLC composition is a later milestone and does not affect the
        // level-data RAM regions compared below.
        assert!(level.tile_count() > 0, "zone ${zone:02X} has no level art");
        assert_eq!(
            level.block_count() as u64,
            row["blockCount"].as_u64().unwrap(),
            "zone ${zone:02X} block count"
        );
        assert_eq!(
            level.loaded_chunk_count() as u64,
            row["chunkCount"].as_u64().unwrap(),
            "zone ${zone:02X} chunk count"
        );

        let mut ram = Ram::new();
        level.fill_level_ram(&mut ram, zone as u8, act as u8);
        let bytes = ram.bytes();
        assert_eq!(
            hex(&bytes[0x0000..0x8000]),
            row["chunks"].as_str().unwrap(),
            "zone ${zone:02X} chunks"
        );
        assert_eq!(
            hex(&bytes[0x8000..0x9000]),
            row["layout"].as_str().unwrap(),
            "zone ${zone:02X} layout"
        );
        assert_eq!(
            hex(&bytes[0x9000..0xA800]),
            row["blocks"].as_str().unwrap(),
            "zone ${zone:02X} blocks"
        );
        assert_eq!(
            hex(&bytes[0xD600..0xDC00]),
            row["collision"].as_str().unwrap(),
            "zone ${zone:02X} collision"
        );
        assert_eq!(
            hex(&bytes[0xFB00..0xFB80]),
            row["palette"].as_str().unwrap(),
            "zone ${zone:02X} palette"
        );
    }
}
